<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_login();$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT p.*,s.seo_title,s.meta_description,s.focus_keyword FROM projects p LEFT JOIN project_seo s ON s.project_id=p.id WHERE p.id=?');$q->execute([$id]);$p=$q->fetch();if(!$p){http_response_code(404);exit('Project not found');}$checks=seo_checklist($p);$pageTitle='SEO Checklist';require __DIR__.'/../../includes/admin_header.php';?><p>Project: <?=e($p['title'])?></p><p>Checklist score: <?=count(array_filter($checks))?> / <?=count($checks)?></p><ul><?php foreach($checks as $label=>$ok):?><li><?= $ok?'[PASS]':'[TODO]'?> <?=e($label)?></li><?php endforeach;?></ul><a href="<?=base_url('admin/projects/edit.php?id='.$id)?>">Back to project</a><?php require __DIR__.'/../../includes/admin_footer.php';
